export const envelope = [15, 26, 15];

export default function build(api) {
  const [W, H, D] = api.size;

  // Safe block placement helper confined to envelope
  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(Math.floor(x), Math.floor(y), Math.floor(z), block);
    }
  }

  // Theme palette extraction with resilient fallbacks
  const theme = api.theme;
  const stonePrimary = theme.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = theme.stone?.accent || "minecraft:chiseled_stone_bricks";
  const stoneSlab = theme.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = theme.stone?.wall || "minecraft:stone_brick_wall";
  const groundPlinth = theme.ground?.plinth || "minecraft:smooth_stone";
  const groundPavement = theme.ground?.pavement || "minecraft:polished_andesite";
  const roofSolid = theme.roof?.solid || "minecraft:stone_bricks";
  const woodFence = theme.wood?.fence || "minecraft:iron_bars";

  // Weathered masonry picker
  function weatheredStone() {
    const r = api.random();
    if (r < 0.25) return "minecraft:mossy_stone_bricks";
    if (r < 0.50) return "minecraft:cracked_stone_bricks";
    return stonePrimary;
  }

  // Record all base footprint columns to conform to real ground
  const groundFootprint = new Set();
  function registerGround(x, z) {
    groundFootprint.add(`${x},${z}`);
  }

  // 1. Mark foundation footprints
  // 4 Corner Pylons
  for (let dx = 2; dx <= 4; dx++) {
    for (let dz = 2; dz <= 4; dz++) {
      registerGround(dx, dz);
      registerGround(W - 1 - dx, dz);
      registerGround(dx, D - 1 - dz);
      registerGround(W - 1 - dx, D - 1 - dz);
    }
  }
  // Central Bunker
  for (let x = 5; x <= 9; x++) {
    for (let z = 5; z <= 9; z++) {
      registerGround(x, z);
    }
  }
  // Conduit trenches
  for (let x = 3; x <= 11; x++) {
    registerGround(x, 7);
  }
  for (let z = 3; z <= 11; z++) {
    registerGround(7, z);
  }

  // 2. Conform Foundation Down to Terrain (seatY = 0)
  for (const entry of groundFootprint) {
    const [sx, sz] = entry.split(",").map(Number);
    const h = api.heightAt(sx, sz);
    const minY = Math.min(0, h);
    const maxY = Math.max(0, h);

    for (let y = minY; y <= maxY; y++) {
      const block = (y < 0) ? groundPlinth : weatheredStone();
      setBlock(sx, y, sz, block);
    }
  }

  // 3. Central Bunker & Equipment Shelter (y = 0 to 4)
  // Floor at y=0
  for (let x = 5; x <= 9; x++) {
    for (let z = 5; z <= 9; z++) {
      setBlock(x, 0, z, groundPavement);
    }
  }

  // Bunker Walls (y = 1 to 3)
  for (let y = 1; y <= 3; y++) {
    for (let x = 5; x <= 9; x++) {
      for (let z = 5; z <= 9; z++) {
        const isWallX = (x === 5 || x === 9);
        const isWallZ = (z === 5 || z === 9);

        if (isWallX || isWallZ) {
          // North Doorway Opening at x=7, z=5
          if (z === 5 && x === 7 && (y === 1 || y === 2)) {
            // Keep doorway clear for entrance
            continue;
          }
          // Door Frame / Accent
          if (z === 5 && (x === 6 || x === 8)) {
            setBlock(x, y, z, stoneAccent);
          } else if (z === 5 && x === 7 && y === 3) {
            setBlock(x, y, z, stoneAccent);
          } else if (y === 2 && ((x === 5 && z === 7) || (x === 9 && z === 7) || (z === 9 && x === 7))) {
            // Ventilation / sensor slit
            setBlock(x, y, z, "minecraft:iron_bars");
          } else {
            setBlock(x, y, z, weatheredStone());
          }
        }
      }
    }
  }

  // Bunker Roof (y = 4)
  for (let x = 5; x <= 9; x++) {
    for (let z = 5; z <= 9; z++) {
      if (x === 7 && z === 7) {
        // High-voltage conduit hub through bunker roof
        setBlock(x, 4, z, "minecraft:polished_blackstone");
      } else {
        setBlock(x, 4, z, roofSolid);
      }
    }
  }

  // 4. Heavy Reinforced Scaffolding & Pylons (y = 0 to 14)
  const cornerCoords = [
    [2, 2], [11, 2], [2, 11], [11, 11]
  ];

  // Rise lower pillars to mid-deck (y = 0 to 8)
  for (let y = 1; y <= 8; y++) {
    for (const [cx, cz] of cornerCoords) {
      const x0 = (cx === 2) ? 2 : 11;
      const x1 = (cx === 2) ? 3 : 12;
      const z0 = (cz === 2) ? 2 : 11;
      const z1 = (cz === 2) ? 3 : 12;

      for (let x = x0; x <= x1; x++) {
        for (let z = z0; z <= z1; z++) {
          setBlock(x, y, z, weatheredStone());
        }
      }

      // Exterior structural corner walls
      setBlock(cx, y, cz, stoneWall);
    }
  }

  // Horizontal Scaffolding Beams at y = 4
  for (let x = 2; x <= 12; x++) {
    setBlock(x, 4, 3, "minecraft:polished_andesite");
    setBlock(x, 4, 11, "minecraft:polished_andesite");
  }
  for (let z = 2; z <= 12; z++) {
    setBlock(3, 4, z, "minecraft:polished_andesite");
    setBlock(11, 4, z, "minecraft:polished_andesite");
  }

  // Cross-bracing trusses between y = 4 and 8
  for (let i = 4; i <= 10; i++) {
    setBlock(i, 6, 3, "minecraft:iron_bars");
    setBlock(i, 6, 11, "minecraft:iron_bars");
    setBlock(3, 6, i, "minecraft:iron_bars");
    setBlock(11, 6, i, "minecraft:iron_bars");
  }

  // Mid-Level Maintenance Catwalk (y = 8)
  for (let x = 2; x <= 12; x++) {
    for (let z = 2; z <= 12; z++) {
      const isOuterRing = (x <= 4 || x >= 10 || z <= 4 || z >= 10);
      if (isOuterRing) {
        setBlock(x, 8, z, stoneSlab);
      }
    }
  }

  // Catwalk Perimeter Railing (y = 9)
  for (let i = 2; i <= 12; i++) {
    setBlock(i, 9, 2, "minecraft:iron_bars");
    setBlock(i, 9, 12, "minecraft:iron_bars");
    setBlock(2, 9, i, "minecraft:iron_bars");
    setBlock(12, 9, i, "minecraft:iron_bars");
  }

  // Auxiliary Tech Gear on Catwalk
  setBlock(3, 9, 7, "minecraft:iron_block");
  setBlock(3, 10, 7, "minecraft:daylight_detector");
  setBlock(11, 9, 7, "minecraft:lodestone");

  // Upper Scaffolding Taper (y = 9 to 14)
  for (let y = 9; y <= 13; y++) {
    // Inward angled pylon columns
    const offset = (y >= 11) ? 4 : 3;
    setBlock(offset, y, offset, "minecraft:polished_andesite");
    setBlock(W - 1 - offset, y, offset, "minecraft:polished_andesite");
    setBlock(offset, y, D - 1 - offset, "minecraft:polished_andesite");
    setBlock(W - 1 - offset, y, D - 1 - offset, "minecraft:polished_andesite");

    // Diagonal iron bracing
    setBlock(offset + 1, y, offset + 1, "minecraft:iron_bars");
    setBlock(W - 2 - offset, y, offset + 1, "minecraft:iron_bars");
    setBlock(offset + 1, y, D - 2 - offset, "minecraft:iron_bars");
    setBlock(W - 2 - offset, y, D - 2 - offset, "minecraft:iron_bars");
  }

  // Central Cable Conduit & Access Ladder (y = 4 to 14)
  for (let y = 4; y <= 14; y++) {
    // Central core conduit
    setBlock(7, y, 7, "minecraft:polished_blackstone");
    // Climbing ladder on south face of the mast
    setBlock(7, y, 8, "minecraft:ladder[facing=south]");
  }

  // 5. Main Array Turret Deck & Gimbal (y = 14 to 16)
  // Gantry Deck Platform at y = 14
  for (let x = 4; x <= 10; x++) {
    for (let z = 4; z <= 10; z++) {
      // Octagonal chamfered corners
      const isCorner = (x === 4 && z === 4) || (x === 10 && z === 4) ||
                       (x === 4 && z === 10) || (x === 10 && z === 10);
      if (!isCorner) {
        setBlock(x, 14, z, "minecraft:polished_andesite");
      }
    }
  }

  // Gantry Deck Railing (y = 15)
  for (let i = 5; i <= 9; i++) {
    setBlock(i, 15, 4, "minecraft:iron_bars");
    setBlock(i, 15, 10, "minecraft:iron_bars");
    setBlock(4, 15, i, "minecraft:iron_bars");
    setBlock(10, 15, i, "minecraft:iron_bars");
  }

  // Heavy Gimbal Turret & Elevation Drive (y = 15 to 16)
  for (let x = 6; x <= 8; x++) {
    for (let z = 6; z <= 8; z++) {
      setBlock(x, 15, z, "minecraft:polished_blackstone");
    }
  }
  setBlock(7, 16, 7, "minecraft:lodestone");
  setBlock(7, 16, 8, "minecraft:polished_blackstone");
  setBlock(6, 16, 7, "minecraft:polished_andesite");
  setBlock(8, 16, 7, "minecraft:polished_andesite");
  setBlock(5, 16, 7, "minecraft:iron_block");
  setBlock(9, 16, 7, "minecraft:iron_block");

  // Hydraulic Actuators
  setBlock(5, 15, 8, "minecraft:polished_andesite");
  setBlock(9, 15, 8, "minecraft:polished_andesite");
  setBlock(7, 15, 9, "minecraft:iron_block");

  // 6. Scavenged Parabolic Satellite Dish (y = 15 to 23)
  // Geometrical paraboloid facing North (-Z) and angled upward at theta = 35 deg
  const dishApexX = 7;
  const dishApexY = 17;
  const dishApexZ = 8;
  const theta = 35 * Math.PI / 180;
  const sinT = Math.sin(theta);
  const cosT = Math.cos(theta);
  const focalLen = 3.2;
  const kParam = 1 / (4 * focalLen);
  const maxRadius = 4.3;

  for (let x = 2; x <= 12; x++) {
    for (let y = 14; y <= 23; y++) {
      for (let z = 4; z <= 12; z++) {
        const dx = x - dishApexX;
        const dy = y - dishApexY;
        const dz = z - dishApexZ;

        // Normal component (along dish beam direction: North & Up)
        const vNorm = dy * sinT - dz * cosT;
        // In-plane vertical component
        const uVert = dy * cosT + dz * sinT;
        // Radial distance from dish axis
        const rad = Math.sqrt(dx * dx + uVert * uVert);

        if (rad <= maxRadius) {
          const vSurf = kParam * rad * rad;
          const distToShell = Math.abs(vNorm - vSurf);

          if (distToShell <= 0.58) {
            if (rad >= 3.6) {
              // Reinforced Perimeter Rim
              setBlock(x, y, z, "minecraft:iron_block");
            } else if (vNorm >= vSurf - 0.1) {
              // Inner Reflective Dish Surface (Smooth Quartz)
              setBlock(x, y, z, "minecraft:smooth_quartz");
            } else {
              // Backing Ribs / Scavenged Solar Backplate
              setBlock(x, y, z, "minecraft:polished_andesite");
            }
          }
        }
      }
    }
  }

  // Central Dish Hub Structural Anchor (ensuring continuous solid connectivity)
  setBlock(7, 17, 8, "minecraft:lodestone");
  setBlock(6, 17, 8, "minecraft:iron_block");
  setBlock(8, 17, 8, "minecraft:iron_block");
  setBlock(7, 18, 8, "minecraft:smooth_quartz");
  setBlock(7, 17, 7, "minecraft:smooth_quartz");

  // High-Tech Feed Horn / Transceiver Sensor Assembly
  // Focal Point at [7, 19, 5]
  setBlock(7, 19, 5, "minecraft:observer[facing=south]");
  setBlock(7, 19, 4, "minecraft:lightning_rod[facing=north]");
  setBlock(7, 19, 6, "minecraft:end_rod[facing=south]");

  // Quadpod Feed Support Struts (connecting dish rim firmly to focal transceiver)
  // Top Strut
  setBlock(7, 21, 7, "minecraft:iron_bars");
  setBlock(7, 20, 6, "minecraft:iron_bars");
  setBlock(7, 19, 5, "minecraft:observer[facing=south]");

  // Bottom Strut
  setBlock(7, 16, 7, "minecraft:iron_bars");
  setBlock(7, 17, 6, "minecraft:iron_bars");
  setBlock(7, 18, 5, "minecraft:iron_bars");

  // West Strut
  setBlock(4, 18, 7, "minecraft:iron_bars");
  setBlock(5, 18, 6, "minecraft:iron_bars");
  setBlock(6, 19, 5, "minecraft:iron_bars");

  // East Strut
  setBlock(10, 18, 7, "minecraft:iron_bars");
  setBlock(9, 18, 6, "minecraft:iron_bars");
  setBlock(8, 19, 5, "minecraft:iron_bars");

  // 7. High-Tech Sensor Spire & Mast (y = 14 to 25)
  // Vertical mast structure at x = 7, z = 9
  for (let y = 14; y <= 18; y++) {
    setBlock(7, y, 9, "minecraft:polished_andesite");
  }
  setBlock(7, 19, 9, "minecraft:iron_block");
  setBlock(7, 20, 9, "minecraft:lodestone");
  setBlock(7, 21, 9, "minecraft:observer[facing=north]");
  setBlock(7, 22, 9, "minecraft:iron_block");

  // Horizontal Dipole Antenna Crossbar at y = 22
  for (let x = 5; x <= 9; x++) {
    if (x !== 7) {
      setBlock(x, 22, 9, "minecraft:iron_bars");
    }
  }
  setBlock(5, 23, 9, "minecraft:end_rod[facing=up]");
  setBlock(9, 23, 9, "minecraft:end_rod[facing=up]");

  // Sensor array pods
  setBlock(7, 20, 10, "minecraft:daylight_detector");
  setBlock(7, 23, 9, "minecraft:chain[axis=y]");

  // Omnidirectional Beacon Light (y = 24) & Sensor Spike (y = 25)
  setBlock(7, 24, 9, "minecraft:sea_lantern");
  setBlock(7, 25, 9, "minecraft:lightning_rod[facing=up]");

  // 8. Apocalyptic Overgrowth & Weathered Foliage
  // Creeping vines on tower base legs
  for (let y = 1; y <= 6; y++) {
    if (api.random() < 0.7) setBlock(1, y, 2, "minecraft:vine[east=true]");
    if (api.random() < 0.7) setBlock(1, y, 12, "minecraft:vine[east=true]");
    if (api.random() < 0.7) setBlock(13, y, 2, "minecraft:vine[west=true]");
    if (api.random() < 0.7) setBlock(13, y, 12, "minecraft:vine[west=true]");
    if (api.random() < 0.7) setBlock(2, y, 1, "minecraft:vine[south=true]");
    if (api.random() < 0.7) setBlock(12, y, 1, "minecraft:vine[south=true]");
    if (api.random() < 0.7) setBlock(2, y, 13, "minecraft:vine[north=true]");
    if (api.random() < 0.7) setBlock(12, y, 13, "minecraft:vine[north=true]");
  }

  // Overgrown leaf clusters clinging to reinforced concrete footings
  const leafClusters = [
    [2, 1, 4], [4, 1, 2], [10, 1, 2], [12, 1, 4],
    [2, 1, 10], [4, 1, 12], [10, 1, 12], [12, 1, 10],
    [3, 5, 2], [11, 5, 2], [3, 5, 12], [11, 5, 12],
    [2, 8, 5], [12, 8, 5], [2, 8, 9], [12, 8, 9]
  ];

  for (const [lx, ly, lz] of leafClusters) {
    const leafType = (api.random() < 0.4)
      ? "minecraft:azalea_leaves[persistent=true]"
      : "minecraft:oak_leaves[persistent=true]";
    setBlock(lx, ly, lz, leafType);
  }

  // Dangling conduit cables under the mid-deck
  setBlock(4, 7, 3, "minecraft:chain[axis=y]");
  setBlock(10, 7, 3, "minecraft:chain[axis=y]");
  setBlock(4, 7, 11, "minecraft:chain[axis=y]");
  setBlock(10, 7, 11, "minecraft:chain[axis=y]");

  return {
    name: "comm_array_tower",
    seatY: 0,
    anchors: {
      front: [7, 1, 0],
      door: [7, 1, 5]
    },
    interiors: [
      {
        min: [6, 1, 6],
        max: [8, 3, 8],
        kind: "laboratory"
      }
    ]
  };
}
